function getUltimateaiTranslation(key, lang) {
  if (ultimateaiTranslations[lang] && ultimateaiTranslations[lang][key]) {
    return ultimateaiTranslations[lang][key];
  }
  if (ultimateaiTranslations.en && ultimateaiTranslations.en[key]) {
    return ultimateaiTranslations.en[key];
  }
  return null;
}

function applyUltimateaiTranslations(lang) {
  console.log(`🔥 Applying ultimateai translations for: ${lang}`);
  let count = 0;
  document.querySelectorAll('[data-i18n]').forEach(element => {
    const key = element.getAttribute('data-i18n');
    if (key && (key.startsWith('review.ultimateai.') || key.startsWith('review.common.'))) {
      const translation = getUltimateaiTranslation(key, lang);
      if (translation) {
        element.textContent = translation;
        count++;
      }
    }
  });
  console.log(`✅ Applied ${count} ultimateai translations`);
}

window.addEventListener('languageChanged', (e) => {
  const lang = e.detail.language;
  setTimeout(() => applyUltimateaiTranslations(lang), 200);
});

if (document.readyState === 'loading') {
  document.addEventListener('DOMContentLoaded', () => {
    const currentLang = window.i18n ? window.i18n.getCurrentLanguage() : 'en';
    applyUltimateaiTranslations(currentLang);
  });
} else {
  const currentLang = window.i18n ? window.i18n.getCurrentLanguage() : 'en';
  applyUltimateaiTranslations(currentLang);
}

console.log('✅ ultimateai i18n loaded');
